mapper.select:
SELECT s.id, s.driver_id, s.delivery_task_id, s.order_id, s.delivery_fee, s.bonus, s.penalty, s.settlement_amount, s.settlement_status, s.settlement_time, s.create_time, s.update_time, s.deleted, d.real_name AS driver_name FROM driver_settlement s LEFT JOIN delivery_driver d ON d.id = s.driver_id WHERE s.deleted = 0
AND s.settlement_status = #{settlementStatus}
ORDER BY s.create_time DESC
